    [Theory]
    [MemberData(nameof(Symbols))]
    public void MatchesReferenceBars(string value, BarcodeType type, string encoded, int modules, string expected)
    {
        var symbol = BarcodeEncoder.Encode(value, type);

        Assert.Equal(encoded, symbol.Value);
        Assert.Equal(modules, symbol.ModuleCount);
        Assert.Equal(expected, Pack(symbol));
    }

    private static string Pack(BarcodeSymbol symbol) =>
        string.Join(
            " ",
            symbol.Bars.Select(b => FormattableString.Invariant($"{b.Start}:{b.Width}:{b.Top:0.###}:{b.Bottom:0.###}")));
}
